frappe.ui.form.on('Supplier', {
    refresh(frm) {
        // Menghapus tombol-tombol tertentu dari form
        frm.remove_custom_button("Accounting Ledger", 'View');
        frm.remove_custom_button("Accounts Payable", 'View');
        frm.remove_custom_button("Bank Account", 'Create');
        frm.remove_custom_button("Pricing Rule", 'Create');
        frm.remove_custom_button("Get Supplier Group Details", 'Actions');
        frm.remove_custom_button("Link with Customer", 'Actions');

        // Memicu fungsi custom untuk menampilkan tabel item
        frm.trigger("custom_list_item_supplier_table");
        
        //filter pada child table address
        frm.set_query("citytown", "custom_address_supplier", function (doc, cdt, cdn) {
            let local = locals[cdt][cdn];
          return {
            "filters": {
              "provinsi": local.stateprovince
            },
          };
        });
    },

    async custom_list_item_supplier_table(frm) {
        let html = '';
        html += `<table class='table table-bordered'>
            <thead>
                <tr>
                    <th>Item Code / Name</th>
                    <th>Group Type</th>
                    <th>Rate</th>
                </tr>
            </thead>
            <tbody>`;

        try {
            // Mengambil data item dari database berdasarkan supplier di child table
            const items = await frappe.db.get_list('Item', {
                filters: [
                        ["Item Supplier", "supplier", "=", frm.doc.name] // Filter berdasarkan supplier di child table
                    ],
                fields: ['name','item_group','valuation_rate']
            });

            // Membuat baris tabel untuk setiap item
            items.forEach(item => {
                html += `<tr>
                    <td>${item.name}</td>
                    <td>${item.item_group}</td>
                    <td>${item.valuation_rate}</td>
                </tr>`;
            });

            html += `</tbody></table>`;

            // Menetapkan HTML ke properti custom field
            frm.set_df_property("custom_list_item_supplier", "options", html);
        } catch (error) {
            console.error("Error fetching items:", error);
            frappe.msgprint("Gagal mengambil data item. Silakan coba lagi.");
        }
    }
});

