frappe.ui.form.on('Work Order Item', {
	form_render(frm,cdt,cdn) {
		// your code here
		var child = locals[cdt][cdn];
		custom_yield_percentage_percent = frm.doc.produced_qty ===0 ? 0 : (frm.doc.produced_qty/child.consumed_qty)
		custom_yield_percentage_good = frm.doc.produced_qty ===0 ? 0 :  (frm.doc.produced_qty/child.transferred_qty)
		//frm.set_value('custom_yield_percentage',custom_yield_percentage_val)
		frappe.model.set_value(cdt,cdn,"custom_yield_percentage",custom_yield_percentage_percent);
		frappe.model.set_value(cdt,cdn,"custom_yield_good",custom_yield_percentage_good);
	}
})

